const items = $input.all();
const email = $('Extract - Standardize Attachments').first().json;

if (items.length === 0) {
  return [{
    json: {
      ...email,
      extracted_text: "(Word doc empty or unreadable)",
      text: email.email_text
    }
  }];
}

// Find the item index and the binary key containing document.xml
let docXmlKey = null;
let foundItemIndex = -1;
let filesFound = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      const fileMeta = item.binary[key];
      const filename = (fileMeta.fileName || fileMeta.filename || '');
      filesFound.push(`${key}: ${filename}`);
      const normalized = filename.toLowerCase().replace(/\\/g, '/');
      if (normalized === 'document.xml' || normalized.endsWith('/document.xml') || normalized === 'word/document.xml' || normalized.endsWith('/word/document.xml')) {
        docXmlKey = key;
        foundItemIndex = i;
        break;
      }
    }
  }
  if (docXmlKey) break;
}

if (!docXmlKey || foundItemIndex === -1) {
  return [{
    json: {
      ...email,
      extracted_text: `(Word doc structure invalid or missing word/document.xml. Files found: ${filesFound.join(', ')})`,
      text: email.email_text
    }
  }];
}

// Read binary buffer of document.xml (Passing the index number now!)
const rawBuffer = await helpers.getBinaryDataBuffer(foundItemIndex, docXmlKey);
const xmlContent = rawBuffer.toString('utf-8');

// Extract text within <w:t> tags (Word text runs)
const matches = [...xmlContent.matchAll(/<w:t[^>]*>(.*?)<\/w:t>/g)];
let plainText = matches.map(m => m[1]).join(' ');

// Simple XML entity decoder
const decodeXml = (str) => {
  return str
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'");
};

return [{
  json: {
    ...email,
    extracted_text: plainText.trim() ? decodeXml(plainText) : `[DEBUG] XML Length: ${xmlContent.length}, Matches Count: ${matches.length}, Raw XML Start: ${xmlContent.substring(0, 300)}`,
    text: email.email_text
  }
}];

const allowedBinary = ['pdf', 'png', 'jpg', 'jpeg', 'webp'];
const allowedExcel = ['xlsx', 'xls'];
const allowedWord = ['docx'];
const allowedText = ['csv', 'txt'];

// Low-threshold filter: drops tiny social icons to save tokens, letting Claude's vision handle the rest
const isSignatureIcon = (file) => {
  const name = (file.fileName || '').toLowerCase();
  const size = file.fileSize || 0;
  const mime = (file.mimeType || '').toLowerCase();

  if (mime.startsWith('image/')) {
    if (size < 5120) return true; // Ignore tiny graphics under 5KB (social icons)
    const sigKeywords = ['fb', 'facebook', 'linkedin', 'twitter', 'instagram', 'youtube', 'pinterest', 'avatar', 'button', 'icon'];
    if (sigKeywords.some(kw => name.includes(kw))) return true;
  }
  return false;
};

const outputItems = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const emailJson = { ...item.json };
  if (emailJson.text) {
    emailJson.email_text = emailJson.text;
  }

  const mainItem = {
    json: {
      ...emailJson,
      has_binary_attachment: false,
      attachment_type: 'none'
    },
    binary: {},
    pairedItem: {
      item: i // Link this output item back to the original email index
    }
  };

  let binaryCount = 0;

  if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      const file = item.binary[key];
      const ext = (file.fileName || '').split('.').pop().toLowerCase();

      if (isSignatureIcon(file)) {
        continue;
      }

      // 1. Multimodal files (PDF, Images) go directly onto the main item
      if (allowedBinary.includes(ext)) {
        mainItem.binary[`data_${binaryCount}`] = { ...file };
        binaryCount++;
        mainItem.json.has_binary_attachment = true;
        mainItem.json.attachment_type = 'binary';
      }
      // 2. Spreadsheets (Excel) -> Output as separate item
      else if (allowedExcel.includes(ext)) {
        outputItems.push({
          json: {
            ...emailJson,
            attachment_type: ext
          },
          binary: {
            data: { ...file }
          },
          pairedItem: {
            item: i
          }
        });
      }
      // 3. Word Documents -> Output as separate item (and rename to .zip for Decompress)
      else if (allowedWord.includes(ext)) {
        outputItems.push({
          json: {
            ...emailJson,
            attachment_type: 'word'
          },
          binary: {
            data: {
              ...file,
              fileName: (file.fileName || 'document.docx').replace(/\.docx$/i, '.zip'),
              fileExtension: 'zip',
              mimeType: 'application/zip'
            }
          },
          pairedItem: {
            item: i
          }
        });
      }
      // 4. CSV / Plain Text -> Output as separate item
      else if (allowedText.includes(ext)) {
        outputItems.push({
          json: {
            ...emailJson,
            attachment_type: 'text'
          },
          binary: {
            data: { ...file }
          },
          pairedItem: {
            item: i
          }
        });
      }
    }
  }

  // Always include the main email item (with text body + PDF/images) in the output list
  outputItems.push(mainItem);
}

return outputItems;

